parameters.jsCode:
const body = $json.body || $json;

const ticketId = body.ticket_id || ('LJ-' + Date.now());
const customerName = body.customer_name || body.name || 'Valued Customer';
const customerEmail = body.customer_email || body.email || '';
const customerPhone = body.customer_phone || body.phone || 'N/A';
const category = body.query_category || body.category || 'General Inquiry';
const message = body.message || '';
const priority = category === 'Bulk Order' ? 'URGENT' : 'STANDARD';
const timestamp = body.timestamp || new Date().toISOString();

return [{
  json: {
    ticket_id: ticketId,
    customer_name: customerName,
    customer_email: customerEmail,
    customer_phone: customerPhone,
    query_category: category,
    message: message,
    priority: priority,
    timestamp: timestamp,
    status: 'received'
  }
}];

